import {Resizable} from "@/cards/resizable";

registerCard("myApp/splitView", Resizable({
  direction: "horizontal",
  handles:   {withHandle: true},
  content:   [
    {
      name:        "sidebar",
      content:     "myApp/sidebar",
      defaultSize: 25,
      minSize:     15,
      maxSize:     40,
      collapsible: true,
    },
    {
      name:        "main",
      content:     "myApp/mainContent",
      defaultSize: 75,
    },
  ],
}));
